def normalize_iban(iban: str) -> str:
    if not isinstance(iban, str):
        raise ValueError("iban must be a string")
    return iban.replace(" ", "").upper()

def validate_iban(iban: str) -> bool:
    if not isinstance(iban, str):
        return False
    try:
        s = normalize_iban(iban)
    except ValueError:
        return False
    try:
        lengths = {"AD": 24, "AT": 20, "BE": 16, "CH": 21, "DE": 22, "ES": 24, "FR": 27, "GB": 22, "IE": 22, "IT": 27, "LU": 20, "NL": 18, "NO": 15, "PL": 28, "PT": 25, "SE": 24}
        country = s[:2]
        expected = lengths.get(country)
        if expected is None:
            return False
        if len(s) != expected:
            return False
        if not ("A" <= s[0] <= "Z" and "A" <= s[1] <= "Z"):
            return False
        if not ("0" <= s[2] <= "9" and "0" <= s[3] <= "9"):
            return False
        for ch in s[4:]:
            if not (("A" <= ch <= "Z") or ("0" <= ch <= "9")):
                return False
        rearranged = s[4:] + s[:4]
        remainder = 0
        for ch in rearranged:
            if "0" <= ch <= "9":
                remainder = (remainder * 10 + (ord(ch) - 48)) % 97
            elif "A" <= ch <= "Z":
                v = ord(ch) - 55
                remainder = (remainder * 100 + v) % 97
            else:
                return False
        return remainder == 1
    except Exception:
        return False
